@IsTest private class DatePrecisionObservation {
 private static final Long BASE=1735689600000L;
 private static Map<String,Object> pair(Datetime left,Datetime right){return new Map<String,Object>{'left'=>left.getTime(),'right'=>right.getTime(),'operator'=>left==right,'equals'=>left.equals(right),'less'=>left<right,'greater'=>left>right};}
 private static void emit(Object value){System.assertEquals('NATIVE_OBSERVATION',JSON.serialize(value));}
 @IsTest static void positiveControl(){System.assertEquals(3,1+2);}
 @IsTest static void customInsert(){
  Map<String,Object> r=new Map<String,Object>();try{
   Datetime submitted=Datetime.newInstance(BASE+123L);
   PrecisionLedger__c row=new PrecisionLedger__c(Name='Insert',OccurredAt__c=submitted);PrecisionLedger__c alias=row;
   r.put('before',row.OccurredAt__c.getTime());insert row;
   PrecisionLedger__c stored=[SELECT OccurredAt__c FROM PrecisionLedger__c WHERE Id=:row.Id];
   r.put('submitted',submitted.getTime());r.put('caller',row.OccurredAt__c.getTime());r.put('alias',alias.OccurredAt__c.getTime());r.put('comparison',pair(row.OccurredAt__c,stored.OccurredAt__c));
  }catch(Exception e){r.put('exceptionType',e.getTypeName());r.put('exceptionMessage',e.getMessage());}emit(r);
 }
 @IsTest static void customUpdate(){
  Map<String,Object> r=new Map<String,Object>();try{
   PrecisionLedger__c row=new PrecisionLedger__c(Name='Update',OccurredAt__c=Datetime.newInstance(BASE));insert row;
   Datetime submitted=Datetime.newInstance(BASE+1456L);row.OccurredAt__c=submitted;PrecisionLedger__c alias=row;
   r.put('before',row.OccurredAt__c.getTime());Database.SaveResult result=Database.update(row,false);r.put('success',result.isSuccess());
   PrecisionLedger__c stored=[SELECT OccurredAt__c FROM PrecisionLedger__c WHERE Id=:row.Id];
   r.put('submitted',submitted.getTime());r.put('caller',row.OccurredAt__c.getTime());r.put('alias',alias.OccurredAt__c.getTime());r.put('comparison',pair(row.OccurredAt__c,stored.OccurredAt__c));
  }catch(Exception e){r.put('exceptionType',e.getTypeName());r.put('exceptionMessage',e.getMessage());}emit(r);
 }
 @IsTest static void customQueriedCopy(){
  Map<String,Object> r=new Map<String,Object>();try{
   PrecisionLedger__c original=new PrecisionLedger__c(Name='Original',OccurredAt__c=Datetime.newInstance(BASE+1L));insert original;
   PrecisionLedger__c first=[SELECT OccurredAt__c FROM PrecisionLedger__c WHERE Id=:original.Id];
   PrecisionLedger__c copied=new PrecisionLedger__c(Name='Copied',OccurredAt__c=first.OccurredAt__c);insert copied;
   PrecisionLedger__c second=[SELECT OccurredAt__c FROM PrecisionLedger__c WHERE Id=:copied.Id];
   r.put('firstStored',first.OccurredAt__c.getTime());r.put('copyCaller',copied.OccurredAt__c.getTime());r.put('comparison',pair(original.OccurredAt__c,second.OccurredAt__c));
  }catch(Exception e){r.put('exceptionType',e.getTypeName());r.put('exceptionMessage',e.getMessage());}emit(r);
 }
 @IsTest static void scalarMilliseconds(){
  Map<String,Object> r=new Map<String,Object>();try{
   List<Object> pairs=new List<Object>();Datetime whole=Datetime.newInstance(BASE);
   for(Long delta:new List<Long>{0L,1L,10L,999L,1000L})pairs.add(pair(whole,Datetime.newInstance(BASE+delta)));
   r.put('pairs',pairs);
  }catch(Exception e){r.put('exceptionType',e.getTypeName());r.put('exceptionMessage',e.getMessage());}emit(r);
 }
 @IsTest static void eventStorageControl(){
  Map<String,Object> r=new Map<String,Object>();try{
   Datetime submitted=Datetime.newInstance(BASE+123L);Event row=new Event(Subject='Precision Event',StartDateTime=submitted,EndDateTime=submitted.addHours(1));Event alias=row;insert row;
   Event stored=[SELECT StartDateTime FROM Event WHERE Id=:row.Id];
   r.put('submitted',submitted.getTime());r.put('caller',row.StartDateTime.getTime());r.put('alias',alias.StartDateTime.getTime());r.put('comparison',pair(row.StartDateTime,stored.StartDateTime));
  }catch(Exception e){r.put('exceptionType',e.getTypeName());r.put('exceptionMessage',e.getMessage());}emit(r);
 }
}

